package com.blog.controller; import com.blog.dto.AuthDtos.*; import com.blog.dto.ProfileDtos.*; import com.blog.service.BlogServices.ProfileService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/users") @RequiredArgsConstructor public class UserController {private final ProfileService profiles;@GetMapping("/profile") public UserResponse profile(Authentication a){return profiles.profile(a.getName());}@PutMapping("/profile") public UserResponse update(@Valid @RequestBody ProfileUpdateRequest r,Authentication a){return profiles.update(r,a.getName());}}
